arguments.content:
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.70.0"
    }
  }

  backend "local" {
    path = "terraform.tfstate"
  }
}

variable "config_path" {
  description = "Path to the ClearLedger deployment configuration (config.json)."
  type        = string
  default     = "/workspace/config/config.json"
}

locals {
  cfg      = jsondecode(file(var.config_path))
  prefix   = local.cfg.resource_prefix
  region   = local.cfg.region
  endpoint = local.cfg.aws_endpoint_url

  azs = ["${local.region}a", "${local.region}b"]

  tags = {
    ClearLedgerDeployment = local.prefix
  }
}

provider "aws" {
  region     = local.region
  access_key = "test"
  secret_key = "test"

  skip_credentials_validation = true
  skip_metadata_api_check     = true
  skip_region_validation      = true
  s3_use_path_style           = true

  endpoints {
    acm            = local.endpoint
    cloudwatch     = local.endpoint
    cloudwatchlogs = local.endpoint
    cognitoidp     = local.endpoint
    dynamodb       = local.endpoint
    ec2            = local.endpoint
    ecs            = local.endpoint
    elasticache    = local.endpoint
    elb            = local.endpoint
    elbv2          = local.endpoint
    events         = local.endpoint
    iam            = local.endpoint
    kms            = local.endpoint
    lambda         = local.endpoint
    rds            = local.endpoint
    s3             = local.endpoint
    scheduler      = local.endpoint
    sqs            = local.endpoint
    sts            = local.endpoint
  }

  default_tags {
    tags = {
      ClearLedgerDeployment = local.prefix
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
}

locals {
  vpc_cidr             = "10.42.0.0/16"
  public_subnet_cidrs  = ["10.42.0.0/24", "10.42.1.0/24"]
  private_subnet_cidrs = ["10.42.10.0/24", "10.42.11.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.prefix}-igw" })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.tags, {
    Name = "${local.prefix}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "${local.prefix}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.prefix}-public-rt" })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.prefix}-private-rt" })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security groups. Rules are declared inline so that Terraform owns the full
# rule set and removes any out-of-band ingress/egress rule on every apply.
# ---------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name                   = "${local.prefix}-alb"
  description            = "ClearLedger ALB: HTTP from the internet, forwards to ECS on 8080"
  vpc_id                 = aws_vpc.main.id
  revoke_rules_on_delete = true

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Forward to API tasks inside the VPC"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.tags, { Name = "${local.prefix}-alb", ClearLedgerSecurityGroup = "alb" })
}

resource "aws_security_group" "ecs" {
  name                   = "${local.prefix}-ecs"
  description            = "ClearLedger API tasks: 8080 from the ALB only"
  vpc_id                 = aws_vpc.main.id
  revoke_rules_on_delete = true

  ingress {
    description     = "API traffic from the ALB"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "AWS control plane and data stores"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, { Name = "${local.prefix}-ecs", ClearLedgerSecurityGroup = "ecs" })
}

resource "aws_security_group" "rds" {
  name                   = "${local.prefix}-rds"
  description            = "ClearLedger PostgreSQL: 5432 from API tasks and VPC workers"
  vpc_id                 = aws_vpc.main.id
  revoke_rules_on_delete = true

  ingress {
    description     = "PostgreSQL from API tasks"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  ingress {
    description = "PostgreSQL from VPC workers"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress = []

  tags = merge(local.tags, { Name = "${local.prefix}-rds", ClearLedgerSecurityGroup = "rds" })
}

resource "aws_security_group" "valkey" {
  name                   = "${local.prefix}-valkey"
  description            = "ClearLedger Valkey: 6379 from API tasks and VPC workers"
  vpc_id                 = aws_vpc.main.id
  revoke_rules_on_delete = true

  ingress {
    description     = "Valkey from API tasks"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  ingress {
    description = "Valkey from VPC workers"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress = []

  tags = merge(local.tags, { Name = "${local.prefix}-valkey", ClearLedgerSecurityGroup = "valkey" })
}

locals {
  kms_usages = ["database", "messaging", "projection", "audit"]

  log_groups = {
    api       = "/clearledger/${local.prefix}/api"
    projector = "/clearledger/${local.prefix}/projector"
    relay     = "/clearledger/${local.prefix}/outbox-relay"
    archiver  = "/clearledger/${local.prefix}/audit-archiver"
  }
}

resource "aws_kms_key" "this" {
  for_each = toset(local.kms_usages)

  description             = "ClearLedger ${local.prefix} ${each.key} key"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  deletion_window_in_days = 10
  is_enabled              = true

  tags = merge(local.tags, {
    Name                = "${local.prefix}-${each.key}"
    ClearLedgerKeyUsage = each.key
  })
}

resource "aws_kms_alias" "this" {
  for_each = toset(local.kms_usages)

  name          = "alias/${local.prefix}-${each.key}"
  target_key_id = aws_kms_key.this[each.key].key_id
}

resource "aws_cloudwatch_log_group" "this" {
  for_each = local.log_groups

  name              = each.value
  retention_in_days = 14

  tags = merge(local.tags, { ClearLedgerWorkload = each.key })
}

# ---------------------------------------------------------------------------
# RDS PostgreSQL (system of record)
# ---------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name        = "${local.prefix}-db-subnets"
  description = "ClearLedger private DB subnets"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.tags, { Name = "${local.prefix}-db-subnets" })
}

resource "aws_db_instance" "main" {
  identifier     = "${local.prefix}-postgres"
  engine         = "postgres"
  engine_version = "16.3"
  instance_class = "db.t4g.micro"

  allocated_storage = 20
  storage_type      = "gp3"
  storage_encrypted = true
  kms_key_id        = aws_kms_key.this["database"].arn

  db_name  = local.cfg.db_name
  username = local.cfg.db_username
  password = local.cfg.db_password
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = false
  multi_az               = false

  backup_retention_period    = 0
  skip_final_snapshot        = true
  deletion_protection        = false
  apply_immediately          = true
  auto_minor_version_upgrade = false

  tags = merge(local.tags, { Name = "${local.prefix}-postgres" })

  lifecycle {
    ignore_changes = [engine_version, allocated_storage, storage_type]
  }
}

# ---------------------------------------------------------------------------
# DynamoDB projection store
# ---------------------------------------------------------------------------

resource "aws_dynamodb_table" "projections" {
  name         = "${local.prefix}-projections"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }

  attribute {
    name = "SK"
    type = "S"
  }

  attribute {
    name = "GSI1PK"
    type = "S"
  }

  attribute {
    name = "GSI1SK"
    type = "S"
  }

  global_secondary_index {
    name            = "AccountIndex"
    hash_key        = "GSI1PK"
    range_key       = "GSI1SK"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.this["projection"].arn
  }

  tags = merge(local.tags, { Name = "${local.prefix}-projections" })
}

# ---------------------------------------------------------------------------
# ElastiCache for Valkey
# ---------------------------------------------------------------------------

resource "aws_elasticache_subnet_group" "main" {
  name        = "${local.prefix}-cache-subnets"
  description = "ClearLedger private cache subnets"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.tags, { Name = "${local.prefix}-cache-subnets" })
}

resource "aws_elasticache_replication_group" "main" {
  replication_group_id = "${local.prefix}-valkey"
  description          = "ClearLedger projection cache"

  engine             = "valkey"
  engine_version     = "8.0"
  node_type          = "cache.t4g.micro"
  num_cache_clusters = 1
  port               = 6379

  subnet_group_name  = aws_elasticache_subnet_group.main.name
  security_group_ids = [aws_security_group.valkey.id]

  automatic_failover_enabled = false
  multi_az_enabled           = false
  transit_encryption_enabled = false
  at_rest_encryption_enabled = false
  apply_immediately          = true

  tags = merge(local.tags, { Name = "${local.prefix}-valkey" })

  lifecycle {
    ignore_changes = [engine_version]
  }
}

# ---------------------------------------------------------------------------
# S3 audit archive
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "audit" {
  bucket        = "${local.prefix}-ledger-audit"
  force_destroy = true

  tags = merge(local.tags, { Name = "${local.prefix}-ledger-audit" })
}

resource "aws_s3_bucket_versioning" "audit" {
  bucket = aws_s3_bucket.audit.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
  bucket = aws_s3_bucket.audit.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this["audit"].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "audit" {
  bucket = aws_s3_bucket.audit.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# SQS main queue and DLQ
# ---------------------------------------------------------------------------

resource "aws_sqs_queue" "dlq" {
  name                      = "${local.prefix}-events-dlq"
  kms_master_key_id         = aws_kms_key.this["messaging"].arn
  message_retention_seconds = 1209600

  tags = merge(local.tags, { Name = "${local.prefix}-events-dlq" })
}

resource "aws_sqs_queue" "main" {
  name                       = "${local.prefix}-events"
  kms_master_key_id          = aws_kms_key.this["messaging"].arn
  visibility_timeout_seconds = 3
  receive_wait_time_seconds  = 2
  message_retention_seconds  = 172800

  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 4
  })

  tags = merge(local.tags, { Name = "${local.prefix}-events" })
}

locals {
  kms_arns = { for k in local.kms_usages : k => aws_kms_key.this[k].arn }

  log_group_arns = {
    for k, name in local.log_groups :
    k => "arn:aws:logs:${local.region}:${local.account_id}:log-group:${name}"
  }

  # Resources for a log group: the group ARN itself and its log streams.
  log_resources = {
    for k, arn in local.log_group_arns : k => [arn, "${arn}:*"]
  }

  queue_arn     = aws_sqs_queue.main.arn
  dlq_arn       = aws_sqs_queue.dlq.arn
  table_arn     = aws_dynamodb_table.projections.arn
  gsi_arn       = "${aws_dynamodb_table.projections.arn}/index/AccountIndex"
  bucket_arn    = aws_s3_bucket.audit.arn
  bucket_object = "${aws_s3_bucket.audit.arn}/*"

  all_kms_arns = [for k in local.kms_usages : local.kms_arns[k]]

  log_write_actions = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
  kms_use_actions   = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
  sqs_core_actions  = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
  ddb_core_actions  = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
  s3_core_actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]

  # Guardrail shared by every role: nobody may disable or delete the CMKs.
  deny_kms_destruction = {
    Sid      = "DenyKmsKeyDestruction"
    Effect   = "Deny"
    Action   = ["kms:DisableKey", "kms:ScheduleKeyDeletion"]
    Resource = local.all_kms_arns
  }

  other_log_resources = {
    for k in keys(local.log_groups) : k => flatten([
      for o, res in local.log_resources : res if o != k
    ])
  }

  role_policies = {
    ecs_execution = {
      Version = "2012-10-17"
      Statement = [
        {
          Sid      = "AllowApiLogWrites"
          Effect   = "Allow"
          Action   = local.log_write_actions
          Resource = local.log_resources["api"]
        },
        local.deny_kms_destruction,
        {
          Sid      = "DenyKmsDataKeyUsage"
          Effect   = "Deny"
          Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
          Resource = local.all_kms_arns
        },
        {
          Sid      = "DenySqs"
          Effect   = "Deny"
          Action   = local.sqs_core_actions
          Resource = [local.queue_arn, local.dlq_arn]
        },
        {
          Sid      = "DenyDynamoDb"
          Effect   = "Deny"
          Action   = local.ddb_core_actions
          Resource = [local.table_arn, local.gsi_arn]
        },
        {
          Sid      = "DenyAuditBucket"
          Effect   = "Deny"
          Action   = local.s3_core_actions
          Resource = [local.bucket_arn, local.bucket_object]
        },
        {
          Sid      = "DenyForeignLogGroups"
          Effect   = "Deny"
          Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
          Resource = local.other_log_resources["api"]
        },
      ]
    }

    ecs_task = {
      Version = "2012-10-17"
      Statement = [
        {
          Sid      = "AllowPublishMainQueue"
          Effect   = "Allow"
          Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
          Resource = [local.queue_arn]
        },
        {
          Sid      = "AllowReadProjections"
          Effect   = "Allow"
          Action   = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"]
          Resource = [local.table_arn, local.gsi_arn]
        },
        {
          Sid      = "AllowKmsMessagingProjection"
          Effect   = "Allow"
          Action   = local.kms_use_actions
          Resource = [local.kms_arns["messaging"], local.kms_arns["projection"]]
        },
        {
          Sid      = "AllowApiLogWrites"
          Effect   = "Allow"
          Action   = local.log_write_actions
          Resource = local.log_resources["api"]
        },
        local.deny_kms_destruction,
        {
          Sid      = "DenyForeignKmsKeys"
          Effect   = "Deny"
          Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
          Resource = [local.kms_arns["database"], local.kms_arns["audit"]]
        },
        {
          Sid      = "DenyConsumeMainQueue"
          Effect   = "Deny"
          Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
          Resource = [local.queue_arn]
        },
        {
          Sid      = "DenyDlq"
          Effect   = "Deny"
          Action   = local.sqs_core_actions
          Resource = [local.dlq_arn]
        },
        {
          Sid      = "DenyMutateProjections"
          Effect   = "Deny"
          Action   = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"]
          Resource = [local.table_arn, local.gsi_arn]
        },
        {
          Sid      = "DenyAuditBucket"
          Effect   = "Deny"
          Action   = local.s3_core_actions
          Resource = [local.bucket_arn, local.bucket_object]
        },
        {
          Sid      = "DenyForeignLogGroups"
          Effect   = "Deny"
          Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
          Resource = local.other_log_resources["api"]
        },
      ]
    }

    projector = {
      Version = "2012-10-17"
      Statement = [
        {
          Sid      = "AllowConsumeMainQueue"
          Effect   = "Allow"
          Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"]
          Resource = [local.queue_arn]
        },
        {
          Sid      = "AllowDeadLetterForwarding"
          Effect   = "Allow"
          Action   = ["sqs:SendMessage"]
          Resource = [local.dlq_arn]
        },
        {
          Sid      = "AllowProjectionUpserts"
          Effect   = "Allow"
          Action   = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:Query"]
          Resource = [local.table_arn, local.gsi_arn]
        },
        {
          Sid      = "AllowKmsMessagingProjection"
          Effect   = "Allow"
          Action   = local.kms_use_actions
          Resource = [local.kms_arns["messaging"], local.kms_arns["projection"]]
        },
        {
          Sid      = "AllowProjectorLogWrites"
          Effect   = "Allow"
          Action   = local.log_write_actions
          Resource = local.log_resources["projector"]
        },
        local.deny_kms_destruction,
        {
          Sid      = "DenyForeignKmsKeys"
          Effect   = "Deny"
          Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
          Resource = [local.kms_arns["database"], local.kms_arns["audit"]]
        },
        {
          Sid      = "DenyPublishMainQueue"
          Effect   = "Deny"
          Action   = ["sqs:SendMessage"]
          Resource = [local.queue_arn]
        },
        {
          Sid      = "DenyConsumeDlq"
          Effect   = "Deny"
          Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
          Resource = [local.dlq_arn]
        },
        {
          Sid      = "DenyProjectionDeletes"
          Effect   = "Deny"
          Action   = ["dynamodb:DeleteItem", "dynamodb:DeleteTable"]
          Resource = [local.table_arn, local.gsi_arn]
        },
        {
          Sid      = "DenyAuditBucket"
          Effect   = "Deny"
          Action   = local.s3_core_actions
          Resource = [local.bucket_arn, local.bucket_object]
        },
        {
          Sid      = "DenyForeignLogGroups"
          Effect   = "Deny"
          Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
          Resource = local.other_log_resources["projector"]
        },
      ]
    }

    relay = {
      Version = "2012-10-17"
      Statement = [
        {
          Sid      = "AllowPublishMainQueue"
          Effect   = "Allow"
          Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
          Resource = [local.queue_arn]
        },
        {
          Sid      = "AllowKmsMessagingDatabase"
          Effect   = "Allow"
          Action   = local.kms_use_actions
          Resource = [local.kms_arns["messaging"], local.kms_arns["database"]]
        },
        {
          Sid      = "AllowRelayLogWrites"
          Effect   = "Allow"
          Action   = local.log_write_actions
          Resource = local.log_resources["relay"]
        },
        local.deny_kms_destruction,
        {
          Sid      = "DenyForeignKmsKeys"
          Effect   = "Deny"
          Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
          Resource = [local.kms_arns["projection"], local.kms_arns["audit"]]
        },
        {
          Sid      = "DenyConsumeMainQueue"
          Effect   = "Deny"
          Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
          Resource = [local.queue_arn]
        },
        {
          Sid      = "DenyDlq"
          Effect   = "Deny"
          Action   = local.sqs_core_actions
          Resource = [local.dlq_arn]
        },
        {
          Sid      = "DenyDynamoDb"
          Effect   = "Deny"
          Action   = local.ddb_core_actions
          Resource = [local.table_arn, local.gsi_arn]
        },
        {
          Sid      = "DenyAuditBucket"
          Effect   = "Deny"
          Action   = local.s3_core_actions
          Resource = [local.bucket_arn, local.bucket_object]
        },
        {
          Sid      = "DenyForeignLogGroups"
          Effect   = "Deny"
          Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
          Resource = local.other_log_resources["relay"]
        },
      ]
    }

    archiver = {
      Version = "2012-10-17"
      Statement = [
        {
          Sid      = "AllowAuditObjectAppend"
          Effect   = "Allow"
          Action   = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"]
          Resource = ["${local.bucket_arn}/ledger-audit/*"]
        },
        {
          Sid      = "AllowAuditBucketMetadata"
          Effect   = "Allow"
          Action   = ["s3:ListBucket", "s3:GetBucketLocation"]
          Resource = [local.bucket_arn]
        },
        {
          Sid      = "AllowKmsAuditDatabase"
          Effect   = "Allow"
          Action   = local.kms_use_actions
          Resource = [local.kms_arns["audit"], local.kms_arns["database"]]
        },
        {
          Sid      = "AllowArchiverLogWrites"
          Effect   = "Allow"
          Action   = local.log_write_actions
          Resource = local.log_resources["archiver"]
        },
        local.deny_kms_destruction,
        {
          Sid      = "DenyForeignKmsKeys"
          Effect   = "Deny"
          Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
          Resource = [local.kms_arns["messaging"], local.kms_arns["projection"]]
        },
        {
          Sid      = "DenyAuditDeletes"
          Effect   = "Deny"
          Action   = ["s3:DeleteObject", "s3:DeleteObjectVersion"]
          Resource = [local.bucket_arn, local.bucket_object]
        },
        {
          Sid       = "DenyPutOutsideAuditPrefix"
          Effect    = "Deny"
          Action    = ["s3:PutObject"]
          NotResource = ["${local.bucket_arn}/ledger-audit/*"]
        },
        {
          Sid      = "DenySqs"
          Effect   = "Deny"
          Action   = local.sqs_core_actions
          Resource = [local.queue_arn, local.dlq_arn]
        },
        {
          Sid      = "DenyDynamoDb"
          Effect   = "Deny"
          Action   = local.ddb_core_actions
          Resource = [local.table_arn, local.gsi_arn]
        },
        {
          Sid      = "DenyForeignLogGroups"
          Effect   = "Deny"
          Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
          Resource = local.other_log_resources["archiver"]
        },
      ]
    }

    scheduler = {
      Version = "2012-10-17"
      Statement = [
        {
          Sid      = "AllowInvokeScheduledWorkers"
          Effect   = "Allow"
          Action   = ["lambda:InvokeFunction"]
          Resource = [aws_lambda_function.relay.arn, aws_lambda_function.archiver.arn]
        },
        local.deny_kms_destruction,
        {
          Sid      = "DenyInvokeProjector"
          Effect   = "Deny"
          Action   = ["lambda:InvokeFunction"]
          Resource = [aws_lambda_function.projector.arn, "${aws_lambda_function.projector.arn}:*"]
        },
        {
          Sid      = "DenyKmsDataKeyUsage"
          Effect   = "Deny"
          Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
          Resource = local.all_kms_arns
        },
        {
          Sid      = "DenySqs"
          Effect   = "Deny"
          Action   = local.sqs_core_actions
          Resource = [local.queue_arn, local.dlq_arn]
        },
        {
          Sid      = "DenyDynamoDb"
          Effect   = "Deny"
          Action   = local.ddb_core_actions
          Resource = [local.table_arn, local.gsi_arn]
        },
        {
          Sid      = "DenyAuditBucket"
          Effect   = "Deny"
          Action   = local.s3_core_actions
          Resource = [local.bucket_arn, local.bucket_object]
        },
        {
          Sid      = "DenyAllLogGroups"
          Effect   = "Deny"
          Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
          Resource = flatten([for k, res in local.log_resources : res])
        },
      ]
    }
  }

  role_trust = {
    ecs_execution = "ecs-tasks.amazonaws.com"
    ecs_task      = "ecs-tasks.amazonaws.com"
    projector     = "lambda.amazonaws.com"
    relay         = "lambda.amazonaws.com"
    archiver      = "lambda.amazonaws.com"
    scheduler     = "scheduler.amazonaws.com"
  }

  role_names = {
    ecs_execution = "${local.prefix}-ecs-execution"
    ecs_task      = "${local.prefix}-ecs-task"
    projector     = "${local.prefix}-projector"
    relay         = "${local.prefix}-outbox-relay"
    archiver      = "${local.prefix}-audit-archiver"
    scheduler     = "${local.prefix}-scheduler"
  }
}

resource "aws_iam_role" "this" {
  for_each = local.role_trust

  name                  = local.role_names[each.key]
  description           = "ClearLedger ${local.prefix} ${each.key} role"
  force_detach_policies = true

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "TrustService"
      Effect    = "Allow"
      Principal = { Service = each.value }
      Action    = "sts:AssumeRole"
    }]
  })

  tags = merge(local.tags, {
    Name            = local.role_names[each.key]
    ClearLedgerRole = each.key
  })
}

resource "aws_iam_role_policy" "this" {
  for_each = local.role_trust

  name   = "${local.role_names[each.key]}-policy"
  role   = aws_iam_role.this[each.key].id
  policy = jsonencode(local.role_policies[each.key])
}

locals {
  db_url = format(
    "postgres://%s:%s@%s:%d/%s",
    urlencode(local.cfg.db_username),
    urlencode(local.cfg.db_password),
    aws_db_instance.main.address,
    aws_db_instance.main.port,
    local.cfg.db_name,
  )

  valkey_host = aws_elasticache_replication_group.main.primary_endpoint_address
  valkey_port = aws_elasticache_replication_group.main.port
  valkey_url  = "redis://${local.valkey_host}:${local.valkey_port}"

  issuer_url = "${local.endpoint}/${aws_cognito_user_pool.main.id}"
  jwks_url   = "${local.endpoint}/${aws_cognito_user_pool.main.id}/.well-known/jwks.json"

  worker_base_env = {
    AWS_REGION            = local.region
    AWS_DEFAULT_REGION    = local.region
    AWS_ACCESS_KEY_ID     = "test"
    AWS_SECRET_ACCESS_KEY = "test"
    AWS_ENDPOINT_URL      = local.endpoint
  }
}

# ---------------------------------------------------------------------------
# Lambda workers
# ---------------------------------------------------------------------------

resource "aws_lambda_function" "projector" {
  function_name = "${local.prefix}-projector"
  role          = aws_iam_role.this["projector"].arn
  package_type  = "Image"
  image_uri     = local.cfg.projector_image
  timeout       = 3
  memory_size   = 256
  architectures = ["x86_64"]

  image_config {
    command     = []
    entry_point = []
  }

  environment {
    variables = merge(local.worker_base_env, {
      PROJECTION_TABLE     = aws_dynamodb_table.projections.name
      VALKEY_URL           = local.valkey_url
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["projector"].name
    })
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["projector"].name
  }

  tags = merge(local.tags, { Name = "${local.prefix}-projector", ClearLedgerWorkload = "projector" })

  depends_on = [aws_iam_role_policy.this]
}

resource "aws_lambda_function" "relay" {
  function_name = "${local.prefix}-outbox-relay"
  role          = aws_iam_role.this["relay"].arn
  package_type  = "Image"
  image_uri     = local.cfg.relay_image
  timeout       = 60
  memory_size   = 256
  architectures = ["x86_64"]

  image_config {
    command     = []
    entry_point = []
  }

  environment {
    variables = merge(local.worker_base_env, {
      DATABASE_URL         = local.db_url
      SQS_QUEUE_URL        = aws_sqs_queue.main.url
      OUTBOX_BATCH_SIZE    = "50"
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["relay"].name
    })
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["relay"].name
  }

  tags = merge(local.tags, { Name = "${local.prefix}-outbox-relay", ClearLedgerWorkload = "relay" })

  depends_on = [aws_iam_role_policy.this]
}

resource "aws_lambda_function" "archiver" {
  function_name = "${local.prefix}-audit-archiver"
  role          = aws_iam_role.this["archiver"].arn
  package_type  = "Image"
  image_uri     = local.cfg.archiver_image
  timeout       = 60
  memory_size   = 256
  architectures = ["x86_64"]

  image_config {
    command     = []
    entry_point = []
  }

  environment {
    variables = merge(local.worker_base_env, {
      DATABASE_URL         = local.db_url
      AUDIT_BUCKET         = aws_s3_bucket.audit.id
      AUDIT_PREFIX         = "ledger-audit/"
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["archiver"].name
    })
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["archiver"].name
  }

  tags = merge(local.tags, { Name = "${local.prefix}-audit-archiver", ClearLedgerWorkload = "archiver" })

  depends_on = [aws_iam_role_policy.this]
}

resource "aws_lambda_event_source_mapping" "projector" {
  event_source_arn                   = aws_sqs_queue.main.arn
  function_name                      = aws_lambda_function.projector.arn
  enabled                            = true
  batch_size                         = 5
  maximum_batching_window_in_seconds = 0
  function_response_types            = ["ReportBatchItemFailures"]

  tags = merge(local.tags, { Name = "${local.prefix}-projector-esm" })
}

# ---------------------------------------------------------------------------
# EventBridge Scheduler
# ---------------------------------------------------------------------------

resource "aws_scheduler_schedule" "outbox" {
  name                = "${local.prefix}-outbox-relay"
  description         = "ClearLedger outbox relay tick"
  schedule_expression = "rate(1 minute)"
  state               = "ENABLED"

  flexible_time_window {
    mode = "OFF"
  }

  target {
    arn      = aws_lambda_function.relay.arn
    role_arn = aws_iam_role.this["scheduler"].arn
    input    = jsonencode({ source = "clearledger.scheduler", job = "outbox-relay" })
  }
}

resource "aws_scheduler_schedule" "archive" {
  name                = "${local.prefix}-audit-archiver"
  description         = "ClearLedger audit archive batch"
  schedule_expression = "rate(5 minutes)"
  state               = "ENABLED"

  flexible_time_window {
    mode = "OFF"
  }

  target {
    arn      = aws_lambda_function.archiver.arn
    role_arn = aws_iam_role.this["scheduler"].arn
    input    = jsonencode({ source = "clearledger.scheduler", job = "audit-archiver" })
  }
}

# ---------------------------------------------------------------------------
# Cognito OAuth2 (client credentials, non-hierarchical scopes)
# ---------------------------------------------------------------------------

resource "aws_cognito_user_pool" "main" {
  name = "${local.prefix}-users"

  tags = merge(local.tags, { Name = "${local.prefix}-users" })
}

resource "aws_cognito_resource_server" "main" {
  identifier   = "clearledger"
  name         = "${local.prefix}-clearledger"
  user_pool_id = aws_cognito_user_pool.main.id

  scope {
    scope_name        = "read"
    scope_description = "Read settlement projections and ledgers"
  }

  scope {
    scope_name        = "write"
    scope_description = "Initiate settlements and append ledger entries"
  }

  scope {
    scope_name        = "admin"
    scope_description = "Rebuild settlement projections"
  }
}

locals {
  client_scopes = {
    read  = "clearledger/read"
    write = "clearledger/write"
    admin = "clearledger/admin"
  }
}

resource "aws_cognito_user_pool_client" "this" {
  for_each = local.client_scopes

  name                                 = "${local.prefix}-${each.key}"
  user_pool_id                         = aws_cognito_user_pool.main.id
  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["client_credentials"]
  allowed_oauth_scopes                 = [each.value]
  supported_identity_providers         = ["COGNITO"]
  explicit_auth_flows                  = ["ALLOW_REFRESH_TOKEN_AUTH"]

  depends_on = [aws_cognito_resource_server.main]
}

# ---------------------------------------------------------------------------
# Application Load Balancer
# ---------------------------------------------------------------------------

resource "aws_lb" "main" {
  name               = "${local.prefix}-alb"
  load_balancer_type = "application"
  internal           = false
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public[*].id
  idle_timeout       = 60

  tags = merge(local.tags, { Name = "${local.prefix}-alb" })
}

resource "aws_lb_target_group" "api" {
  name                 = "${local.prefix}-api"
  port                 = 8080
  protocol             = "HTTP"
  target_type          = "ip"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 5

  health_check {
    enabled             = true
    path                = "/health/ready"
    protocol            = "HTTP"
    port                = "traffic-port"
    matcher             = "200"
    interval            = 5
    timeout             = 2
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = merge(local.tags, { Name = "${local.prefix}-api" })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.api.arn
  }

  tags = merge(local.tags, { Name = "${local.prefix}-http" })
}

# ---------------------------------------------------------------------------
# ECS Fargate API service
# ---------------------------------------------------------------------------

resource "aws_ecs_cluster" "main" {
  name = "${local.prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = merge(local.tags, { Name = "${local.prefix}-cluster" })
}

resource "aws_ecs_task_definition" "api" {
  family                   = "${local.prefix}-api"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.this["ecs_execution"].arn
  task_role_arn            = aws_iam_role.this["ecs_task"].arn

  container_definitions = jsonencode([
    {
      name      = "api"
      image     = local.cfg.api_image
      essential = true
      portMappings = [{
        containerPort = 8080
        hostPort      = 8080
        protocol      = "tcp"
      }]
      environment = [
        for k, v in {
          PORT                  = "8080"
          AWS_REGION            = local.region
          AWS_DEFAULT_REGION    = local.region
          AWS_ACCESS_KEY_ID     = "test"
          AWS_SECRET_ACCESS_KEY = "test"
          AWS_ENDPOINT_URL      = local.endpoint
          DATABASE_URL          = local.db_url
          SQS_QUEUE_URL         = aws_sqs_queue.main.url
          PROJECTION_TABLE      = aws_dynamodb_table.projections.name
          VALKEY_URL            = local.valkey_url
          CACHE_TTL_SECONDS     = "90"
          AUTH_ISSUER           = local.issuer_url
          AUTH_AUDIENCES        = join(",", [for k in ["read", "write", "admin"] : aws_cognito_user_pool_client.this[k].id])
          AUTH_JWKS_URL         = local.jwks_url
          CLOUDWATCH_LOG_GROUP  = aws_cloudwatch_log_group.this["api"].name
        } : { name = k, value = v }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.this["api"].name
          awslogs-region        = local.region
          awslogs-stream-prefix = "api"
        }
      }
    }
  ])

  tags = merge(local.tags, { Name = "${local.prefix}-api" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_ecs_service" "api" {
  name            = "${local.prefix}-api"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.api.arn
  launch_type     = "FARGATE"
  desired_count   = 2

  deployment_minimum_healthy_percent = 100
  deployment_maximum_percent         = 200
  health_check_grace_period_seconds  = 30
  wait_for_steady_state              = false

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.api.arn
    container_name   = "api"
    container_port   = 8080
  }

  tags = merge(local.tags, { Name = "${local.prefix}-api" })

  depends_on = [aws_lb_listener.http, aws_iam_role_policy.this]
}

locals {
  alb_dns_name = aws_lb.main.dns_name
  service_url  = "http://${aws_lb.main.dns_name}"
}

output "manifest" {
  description = "ClearLedger submission manifest (manifest.schema.json)."
  sensitive   = true
  value = {
    resource_prefix = local.prefix
    region          = local.region
    service_url     = local.service_url

    network = {
      vpc_id             = aws_vpc.main.id
      public_subnet_ids  = aws_subnet.public[*].id
      private_subnet_ids = aws_subnet.private[*].id
      security_group_ids = {
        alb    = aws_security_group.alb.id
        ecs    = aws_security_group.ecs.id
        rds    = aws_security_group.rds.id
        valkey = aws_security_group.valkey.id
      }
    }

    ingress = {
      alb_arn          = aws_lb.main.arn
      alb_dns_name     = aws_lb.main.dns_name
      listener_arn     = aws_lb_listener.http.arn
      target_group_arn = aws_lb_target_group.api.arn
      container_port   = 8080
    }

    compute = {
      cluster_arn         = aws_ecs_cluster.main.arn
      cluster_name        = aws_ecs_cluster.main.name
      service_arn         = aws_ecs_service.api.id
      service_name        = aws_ecs_service.api.name
      task_definition_arn = aws_ecs_task_definition.api.arn
      desired_count       = aws_ecs_service.api.desired_count
    }

    database = {
      instance_id  = aws_db_instance.main.identifier
      instance_arn = aws_db_instance.main.arn
      endpoint     = aws_db_instance.main.address
      port         = aws_db_instance.main.port
      db_name      = local.cfg.db_name
      username     = local.cfg.db_username
    }

    messaging = {
      queue_name                = aws_sqs_queue.main.name
      queue_url                 = aws_sqs_queue.main.url
      queue_arn                 = aws_sqs_queue.main.arn
      dlq_name                  = aws_sqs_queue.dlq.name
      dlq_url                   = aws_sqs_queue.dlq.url
      dlq_arn                   = aws_sqs_queue.dlq.arn
      event_source_mapping_uuid = aws_lambda_event_source_mapping.projector.uuid
      max_receive_count         = 4
    }

    workers = {
      projector = {
        function_name = aws_lambda_function.projector.function_name
        function_arn  = aws_lambda_function.projector.arn
      }
      outbox_relay = {
        function_name = aws_lambda_function.relay.function_name
        function_arn  = aws_lambda_function.relay.arn
      }
      audit_archiver = {
        function_name = aws_lambda_function.archiver.function_name
        function_arn  = aws_lambda_function.archiver.arn
      }
    }

    projections = {
      table_name = aws_dynamodb_table.projections.name
      table_arn  = aws_dynamodb_table.projections.arn
      gsi_name   = "AccountIndex"
    }

    cache = {
      cluster_id = aws_elasticache_replication_group.main.id
      engine     = aws_elasticache_replication_group.main.engine
      endpoint   = local.valkey_host
      port       = local.valkey_port
    }

    audit = {
      bucket_name = aws_s3_bucket.audit.id
